/* Lesson data: Floyd-Warshall (structure mode). Steps are generated by simulating the algorithm. */
(function () {
  var names = ['A', 'B', 'C', 'D'];
  var pos = [[90, 70], [340, 70], [340, 200], [90, 200]];
  var edges = [[0, 1, 3], [1, 2, 1], [2, 3, 1], [3, 0, 2], [0, 2, 7]];
  var INF = 1e9, n = 4;
  var mx0 = 610, mdx = 90, my0 = 81, mdy = 46;

  function fmt(x) { return x >= INF ? 'inf' : String(x); }
  function cell(i, j) { return 'm' + i + j; }

  function build() {
    var ops = [], used = {};
    names.forEach(function (nm, i) { ops.push(['node', 'v' + i, nm, pos[i][0], pos[i][1], 'circle']); });
    edges.forEach(function (e, k) {
      used[e[0]] = (used[e[0]] || 0) + 1;
      ops.push(['edge', 'v' + e[0], 'v' + e[1], 'e' + used[e[0]]]);
      var mxp = Math.round((pos[e[0]][0] + pos[e[1]][0]) / 2), myp = Math.round((pos[e[0]][1] + pos[e[1]][1]) / 2);
      ops.push(['node', 'w' + k, String(e[2]), mxp, myp, 'cell'], ['tag', 'w' + k, 'dim']);
    });
    var d = [];
    for (var i = 0; i < n; i++) { d.push([]); for (var j = 0; j < n; j++) d[i].push(i === j ? 0 : INF); }
    edges.forEach(function (e) { d[e[0]][e[1]] = e[2]; });
    names.forEach(function (nm, i) {
      ops.push(['node', 'rh' + i, nm, mx0 - mdx, my0 + i * mdy, 'cell'], ['tag', 'rh' + i, 'dim']);
      ops.push(['node', 'ch' + i, nm, mx0 + i * mdx, my0 - mdy, 'cell'], ['tag', 'ch' + i, 'dim']);
    });
    for (var a = 0; a < n; a++) for (var b = 0; b < n; b++) ops.push(['node', cell(a, b), fmt(d[a][b]), mx0 + b * mdx, my0 + a * mdy, 'cell']);
    return { ops: ops, d: d };
  }

  function run() {
    var g = build(), d = g.d, steps = [];
    steps.push({ pl: 0, cl: 0, h: 380, say: 'Floyd-Warshall finds the shortest path between EVERY pair of vertices. The matrix on the right starts as the direct edge weights: 0 on the diagonal, inf where there is no edge. Rows are "from", columns are "to".', csay: 'dist = copy of the weight matrix.', ds: g.ops });
    var prevK = null, total = 0;
    for (var k = 0; k < n; k++) {
      var intro = [];
      if (prevK !== null) intro.push(['untag', 'v' + prevK, 'cur']);
      intro.push(['tag', 'v' + k, 'cur']);
      steps.push({ pl: 1, cl: 1, h: 380, say: 'k = ' + names[k] + ': allow ' + names[k] + ' as an intermediate stop. For every pair (i, j) ask: is going i to ' + names[k] + ' to j shorter than the best route known so far?', csay: 'Outer loop k = ' + k + '.', ds: intro });
      prevK = k;
      var changed = 0;
      for (var i = 0; i < n; i++) for (var j = 0; j < n; j++) {
        if (i === k || j === k || i === j) continue;
        if (d[i][k] >= INF || d[k][j] >= INF) continue;
        var cand = d[i][k] + d[k][j];
        if (cand < d[i][j]) {
          var old = d[i][j];
          d[i][j] = cand; changed++; total++;
          steps.push({ pl: 4, cl: 4, h: 380, say: names[i] + ' to ' + names[j] + ' via ' + names[k] + ': ' + d[i][k] + ' + ' + d[k][j] + ' = ' + cand + ' beats ' + fmt(old) + '. Update the matrix.', csay: 'dist[' + i + '][' + j + '] = ' + cand + ';', ds: [['lab', cell(i, j), String(cand)], ['hot', cell(i, k), cell(k, j), cell(i, j)]] });
        }
      }
      steps.push({ pl: 1, cl: 1, h: 380, say: changed ? 'Finished k = ' + names[k] + ': ' + changed + ' pair' + (changed > 1 ? 's' : '') + ' improved by routing through ' + names[k] + '.' : 'Finished k = ' + names[k] + ': no pair improved, because no useful new route passes through it.', csay: 'Next k.', ds: [] });
    }
    steps.push({ pl: -1, cl: -1, h: 380, say: 'Done after three nested loops: n x n x n = 64 checks, O(V^3). Row i of the matrix is now the shortest distance from i to every vertex. A negative number on the diagonal would reveal a negative cycle.', csay: 'All pairs solved.', ds: [['untag', 'v' + prevK, 'cur']] });
    return steps;
  }

  var py = ['dist = [row[:] for row in w]    # 0 on diagonal, INF if no edge', 'for k in range(n):                  # allowed intermediate vertex', '    for i in range(n):', '        for j in range(n):', '            if dist[i][k] + dist[k][j] < dist[i][j]:', '                dist[i][j] = dist[i][k] + dist[k][j]'];
  var c = ['memcpy(dist, w, sizeof dist);        /* 0 on diagonal, INF if no edge */', 'for (int k = 0; k < n; k++)           /* allowed intermediate vertex */', '    for (int i = 0; i < n; i++)', '        for (int j = 0; j < n; j++)', '            if (dist[i][k] + dist[k][j] < dist[i][j])', '                dist[i][j] = dist[i][k] + dist[k][j];'];

  window.LESSON = {
    id: 'floyd-warshall',
    mode: 'ds',
    title: 'Floyd-Warshall: all pairs',
    lede:
      'Dijkstra and Bellman-Ford answer "shortest paths from ONE source". Floyd-Warshall answers it for every pair at once, in only three nested loops. The idea is dynamic programming: after round k, dist[i][j] is the shortest path that uses only the first k vertices as stops. Adding vertex k either helps (i to k then k to j is shorter) or it does not. O(V^3) time and O(V^2) space make it a good fit for small dense graphs, such as a few hundred vertices.',
    scenes: [
      { id: 'matrix', title: 'The distance matrix', blurb: 'Round k lets vertex k act as a stop-over; the matrix improves in place.', trap: 'The loop order matters: k MUST be the outermost loop. Putting i or j outside gives wrong answers. Also guard INF + INF: skip the pair when either part is unreachable (in C use a large INF such as 1e9, not INT_MAX, which overflows when added).', pyCode: py, cCode: c, predict: { q: 'Which loop must be outermost in Floyd-Warshall?', options: ['i, the source row', 'k, the allowed intermediate vertex', 'j, the destination column'], answer: 1, why: 'Each round must finish using "stops among 0..k" for ALL pairs before k + 1 is allowed. That is the dynamic-programming order.' }, steps: run() },
    ],
    builtins: [
      ['float("inf")', 'Unreachable marker; inf + x stays inf in Python.'],
      ['[row[:] for row in w]', 'Copy a matrix so the input is not modified.'],
      ['dist[i][i] < 0', 'After the run, a negative diagonal entry means a negative cycle.'],
      ['next[i][j]', 'Store the first hop to rebuild actual paths, not only distances.'],
      ['itertools.product(range(n), repeat=2)', 'Flatten the i and j loops if you like.'],
    ],
  };
})();
